    case runFollowUpTaskReviewActionID:
        return "Explain changes"
    case "bug-analysis":
        return "Read-only triage"
    case "log-analysis":
        return "Read-only trace"
    case "skill-hardening":
        return "Ask before edits"
    case "continue":
        return "Continue turn"
    case "mr-review":
        return "Read-only review"
    case "validation":
        return "Validate only"
    case "jira-update":
        return "Read-only update"
    case "capture-evidence":
        return "Read-only capture"
    default:
        switch permissionMode {
        case .readOnly:
            return "Read-only"
        case .askBeforeEdit:
            return "Ask before edits"
        case .autopilot:
            return "Autopilot"
        case nil:
            return "Follow-up"
        }
    }
}

