    case "bug-analysis":
        return "Triage"
    case "log-analysis":
        return "Trace"
    case "skill-hardening":
        return "Hardening"
    case "continue":
        return "Continue"
    case "mr-review":
        return "MR"
    case "validation":
        return "Verify"
    case "jira-update", "jira-execution":
