        case .toolCard:
            return "Command"
        case .artifactCard:
            return "Artifact"
        case .fileCard:
            return "File"
        case .evidenceCard, .saveEvidence:
            return "Evidence"
        case .handoffDraft:
            return "Draft"
        case .knowledgeNote, .knowledgeCompare:
            return "Knowledge"
        case .none:
