            .fill(
                LinearGradient(
                    colors: [
                        PKTheme.surfaceRaised.opacity(0.95),
                        PKTheme.text3.opacity(0.45)
                    ],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
            )
            .overlay(
                RoundedRectangle(cornerRadius: size * 0.05, style: .continuous)
