    private var latestId: String? {
        entries.last?.id
    }

    var body: some View {
        VStack(spacing: 12) {
            HStack(alignment: .center, spacing: 10) {
                ZStack {
                    Circle()
                        .fill(color.opacity(isLive ? 0.22 : 0.10))
                        .frame(width: 20, height: 20)
                    Circle()
                        .fill(isLive ? color : Color.white.opacity(0.28))
