    var copyOutput: ((Artifact) -> Void)? = nil
    var stageOutput: ((Artifact) -> Void)? = nil
    var startSideChat: ((AgentRun, RunFollowUpAction) -> Void)? = nil
    var resolveBranch: ((Artifact, ArtifactBranchResolution, EntityID?) -> Void)? = nil
