    switch label {
    case "Triage":
        return PKTheme.err
    case "MR":
        return PKTheme.primary
    case "Write-back":
        return PKTheme.warn
    case "Hardening":
        return PKTheme.ok
    case "Handoff":
        return PKTheme.primary
    default:
        return PKTheme.text3
    }
}

