private extension NativeNotificationReadiness {
    var requiresWorkflowAttention: Bool {
        !canSchedule
    }

    var workflowAttentionSymbol: String {
        switch self {
        case .denied:
            "bell.slash"
        case .notDetermined:
            "bell.badge"
        case .unknown:
            "questionmark.circle"
        case .authorized, .provisional, .ephemeral:
            "bell"
        }
    }
}

