private func dedupedSourceRefs(_ refs: [SourceRef]) -> [SourceRef] {
    var seen = Set<String>()
    var out: [SourceRef] = []
    for ref in refs {
        let key = "\(ref.kind)|\(ref.label)|\(ref.uri ?? "")"
        guard !seen.contains(key) else { continue }
        seen.insert(key)
        out.append(ref)
    }
    return out
}

